import Complex128Array = require( '@stdlib/array/complex128' );
import izamax = require( './index' );


// TESTS //

// The function returns a number...
{
	const zx = new Complex128Array( 10 );

	izamax( zx.length, zx, 1 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const zx = new Complex128Array( 10 );

	izamax( '10', zx, 1 ); // $ExpectError
	izamax( true, zx, 1 ); // $ExpectError
	izamax( false, zx, 1 ); // $ExpectError
	izamax( null, zx, 1 ); // $ExpectError
	izamax( undefined, zx, 1 ); // $ExpectError
	izamax( [], zx, 1 ); // $ExpectError
	izamax( {}, zx, 1 ); // $ExpectError
	izamax( ( x: number ): number => x, zx, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a Complex128Array...
{
	const zx = new Complex128Array( 10 );

	izamax( zx.length, 10, 1 ); // $ExpectError
	izamax( zx.length, '10', 1 ); // $ExpectError
	izamax( zx.length, true, 1 ); // $ExpectError
	izamax( zx.length, false, 1 ); // $ExpectError
	izamax( zx.length, null, 1 ); // $ExpectError
	izamax( zx.length, undefined, 1 ); // $ExpectError
	izamax( zx.length, [], 1 ); // $ExpectError
	izamax( zx.length, {}, 1 ); // $ExpectError
	izamax( zx.length, ( zx: number ): number => zx, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const zx = new Complex128Array( 10 );

	izamax( zx.length, zx, '10' ); // $ExpectError
	izamax( zx.length, zx, true ); // $ExpectError
	izamax( zx.length, zx, false ); // $ExpectError
	izamax( zx.length, zx, null ); // $ExpectError
	izamax( zx.length, zx, undefined ); // $ExpectError
	izamax( zx.length, zx, [] ); // $ExpectError
	izamax( zx.length, zx, {} ); // $ExpectError
	izamax( zx.length, zx, ( zx: number ): number => zx ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const zx = new Complex128Array( 10 );

	izamax(); // $ExpectError
	izamax( zx.length ); // $ExpectError
	izamax( zx.length, zx ); // $ExpectError
	izamax( zx.length, zx, 1, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a number...
{
	const zx = new Complex128Array( 10 );

	izamax.ndarray( zx.length, zx, 1, 0 ); // $ExpectType number
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const zx = new Complex128Array( 10 );

	izamax.ndarray( '10', zx, 1, 0 ); // $ExpectError
	izamax.ndarray( true, zx, 1, 0 ); // $ExpectError
	izamax.ndarray( false, zx, 1, 0 ); // $ExpectError
	izamax.ndarray( null, zx, 1, 0 ); // $ExpectError
	izamax.ndarray( undefined, zx, 1, 0 ); // $ExpectError
	izamax.ndarray( [], zx, 1, 0 ); // $ExpectError
	izamax.ndarray( {}, zx, 1, 0 ); // $ExpectError
	izamax.ndarray( ( zx: number ): number => zx, zx, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a Complex128Array...
{
	const zx = new Complex128Array( 10 );

	izamax.ndarray( zx.length, 10, 1, 0 ); // $ExpectError
	izamax.ndarray( zx.length, '10', 1, 0 ); // $ExpectError
	izamax.ndarray( zx.length, true, 1, 0 ); // $ExpectError
	izamax.ndarray( zx.length, false, 1, 0 ); // $ExpectError
	izamax.ndarray( zx.length, null, 1, 0 ); // $ExpectError
	izamax.ndarray( zx.length, undefined, 1, 0 ); // $ExpectError
	izamax.ndarray( zx.length, [], 1, 0 ); // $ExpectError
	izamax.ndarray( zx.length, {}, 1, 0 ); // $ExpectError
	izamax.ndarray( zx.length, ( zx: number ): number => zx, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a number...
{
	const zx = new Complex128Array( 10 );

	izamax.ndarray( zx.length, zx, '10', 0 ); // $ExpectError
	izamax.ndarray( zx.length, zx, true, 0 ); // $ExpectError
	izamax.ndarray( zx.length, zx, false, 0 ); // $ExpectError
	izamax.ndarray( zx.length, zx, null, 0 ); // $ExpectError
	izamax.ndarray( zx.length, zx, undefined, 0 ); // $ExpectError
	izamax.ndarray( zx.length, zx, [], 0 ); // $ExpectError
	izamax.ndarray( zx.length, zx, {}, 0 ); // $ExpectError
	izamax.ndarray( zx.length, zx, ( zx: number ): number => zx, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a number...
{
	const zx = new Complex128Array( 10 );

	izamax.ndarray( zx.length, zx, 1, '10' ); // $ExpectError
	izamax.ndarray( zx.length, zx, 1, true ); // $ExpectError
	izamax.ndarray( zx.length, zx, 1, false ); // $ExpectError
	izamax.ndarray( zx.length, zx, 1, null ); // $ExpectError
	izamax.ndarray( zx.length, zx, 1, undefined ); // $ExpectError
	izamax.ndarray( zx.length, zx, 1, [] ); // $ExpectError
	izamax.ndarray( zx.length, zx, 1, {} ); // $ExpectError
	izamax.ndarray( zx.length, zx, 1, ( zx: number ): number => zx ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const zx = new Complex128Array( 10 );

	izamax.ndarray(); // $ExpectError
	izamax.ndarray( zx.length ); // $ExpectError
	izamax.ndarray( zx.length, zx ); // $ExpectError
	izamax.ndarray( zx.length, zx, 1 ); // $ExpectError
	izamax.ndarray( zx.length, zx, 1, 0, 10 ); // $ExpectError
}
